const P = ROWS.map((r, i) => { const o = { i }; K.forEach((k, j) => o[k] = r[j]); return o; }).filter(x => !/butcher|grocer|supermarket/i.test(x.c)).map((x, i) => Object.assign(x, { i }));
const CUIS = [['peri', 'Peri peri', /peri|piri/i], ['desi', 'Pakistani & Indian', /pakistani|indian|desi|karahi|kashmiri|biryani|curry|bangladeshi|tandoori|lahori|roti|kerala|goan|tawa/i], ['grill', 'Grill & kebabs', /kebab|grill|shawarma|turkish|lebanese|mediterranean|greek|arabic|middle eastern|afghan|yemeni|mandi|souvlaki|gyros|bbq|platters/i],
  ['burger', 'Burgers', /burger/i], ['chicken', 'Chicken', /chicken|wings/i], ['pizza', 'Pizza', /pizza/i], ['steak', 'Steakhouse', /steak/i], ['chai', 'Chai & cafes', /chai|cafe|coffee|lounge/i], ['sweet', 'Desserts & sweets', /dessert|sweet|baklava|bakery|cake/i], ['asian', 'Chinese & Asian', /chinese|noodle|asian|wok/i], ['fish', 'Fish & chips', /fish/i]];
const grp = x => /cafe|sweet|bakery|dessert/i.test(x.c) ? 'cafe' : 'eat';
P.forEach(x => { x.g = grp(x); x.cu = CUIS.filter(c => c[2].test(x.f + ' ' + x.n + ' ' + x.c)).map(c => c[0]); x.closed = /possibly closed/i.test(x.st); x.rn = x.r === '' ? -1 : +x.r; x.cheap = /under £10/.test(x.p); });
const S = Object.assign({ q: '', cu: '', g: '', town: '', hmc: 0, hy: 0, cheap: 0, more: 0, sort: 'rec', me: null, meL: '' }, store.get('hfood', {}), { q: '' });
const save = () => { const { q, ...k } = S; store.set('hfood', k); };
const conf = { hmc: 3, says: 2, check: 1 };
const dist = x => S.me && x.ll ? X.miles(S.me, x.ll) : null;
const mi = m => m == null ? '' : m < .1 ? 'Under 0.1 mi' : m.toFixed(m < 10 ? 1 : 0) + ' mi';
const HB = { hmc: ['HMC certified', 'ok'], says: ['Says halal', 'say'], check: ['Not confirmed', 'chk'] };
const hyg = x => `<span class="hf-hy r${x.rn < 0 ? 'n' : x.rn}" aria-label="Food hygiene rating ${x.rn < 0 ? 'not yet given' : x.rn + ' out of 5'}"><b>${x.rn < 0 ? '–' : x.rn}</b><small>${x.rn < 0 ? (/new/i.test(x.st) ? 'New' : 'Not rated') : 'Hygiene'}</small></span>`;
const maps = x => 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent([x.n, x.a, x.pc || x.t].filter(Boolean).join(', '));
const fsa = x => 'https://www.google.com/search?q=' + encodeURIComponent(`${x.n} ${x.pc || x.t} food hygiene rating site:ratings.food.gov.uk`);
const when = d => { if (!d) return ''; const t = new Date(d); return isNaN(t) ? d : t.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' }); };

function list() {
  const q = S.q.trim().toLowerCase();
  let L = P.filter(x => (S.more || (x.hs !== 'check' && !x.closed)) && (!S.g || x.g === S.g) && (!S.cu || x.cu.includes(S.cu)) && (!S.town || x.t === S.town) && (!S.hmc || x.hs === 'hmc') && (!S.cheap || x.cheap)
    && (!q || (x.n + ' ' + x.f + ' ' + x.c + ' ' + x.a + ' ' + x.pc + ' ' + x.t).toLowerCase().includes(q)));
  const by = { rec: (a, b) => (b.closed ? -9 : 0) - (a.closed ? -9 : 0) || conf[b.hs] - conf[a.hs] || a.n.localeCompare(b.n), near: (a, b) => (dist(a) ?? 1e9) - (dist(b) ?? 1e9), hyg: (a, b) => b.rn - a.rn || a.n.localeCompare(b.n), az: (a, b) => a.n.localeCompare(b.n) };
  return L.sort(by[S.sort === 'near' && !S.me ? 'rec' : S.sort]);
}
